#include<bits/stdc++.h>using namespace std; int main(){    int n;    cin >> n;    int sum =0;    vector<int> a(n);    for(int i=0;i<n;i++)    {        cin >> a[i];        sum +=a[i];    }    sort(a.begin(),a.end(),greater<int>());    int csum =0;    int j=0;    for(int i=0;i<n;i++)    {        csum += a[i];        j++;        if(csum > sum-csum)        {            break;        }    }    cout << j << endl;}